const userStoryHasActiveWorkItems = `-- name: UserStoryHasActiveWorkItems :one
SELECT EXISTS (
    SELECT 1
    FROM work_items
    WHERE user_story_id = $1
      AND workspace_id = $2
      AND deleted_at IS NULL
)
`

type UserStoryHasActiveWorkItemsParams struct {
	UserStoryID pgtype.UUID `json:"user_story_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

func (q *Queries) UserStoryHasActiveWorkItems(ctx context.Context, arg UserStoryHasActiveWorkItemsParams) (bool, error) {
	row := q.db.QueryRow(ctx, userStoryHasActiveWorkItems, arg.UserStoryID, arg.WorkspaceID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

